LABELS = {"tr":"Türkçe", "en":"English", "de":"Deutsch", "fr":"Français", "es":"Español", "it":"Italiano", "pt":"Português", "nl":"Nederlands", "pl":"Polski", "ru":"Русский", "ar":"العربية", "zh":"中文", "ja":"日本語", "ko":"한국어", "hi":"हिन्दी", "id":"Bahasa Indonesia"}


def _build() -> dict[str, dict[str, str]]:
    translations = {}
    for code, raw in DATA.items():
        values = raw.split("|")
        if len(values) != len(ORDER):
            raise ValueError(f"Incomplete {code} translations: {len(values)} vs {len(ORDER)}")
        translations[code] = dict(zip(ORDER, values))
    return translations

TRANSLATIONS = _build()


def translate(code: str, key: str, **args) -> str:
    value = TRANSLATIONS.get(code, TRANSLATIONS["en"]).get(key, TRANSLATIONS["en"].get(key, key))
    return value.format(**args) if args else value


